import React, { useState } from 'react';

const ContentForm = ({ threadId, onCreate }) => {
  const [title, setTitle] = useState('');
  const [body, setBody] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    // Si hay threadId hacemos un post, si no, creamos un hilo
    const payload = threadId ? { threadId, body } : { title, body };
    console.log('Crear:', payload);
    setTitle(''); setBody('');
    if (onCreate) onCreate(payload);
  };

  return (
    <form onSubmit={handleSubmit} style={{ marginTop: '0.5rem' }}>
      {!threadId && <input placeholder="Título del hilo" value={title} onChange={(e)=>setTitle(e.target.value)} />}
      <textarea placeholder={threadId ? 'Responder al hilo...' : 'Contenido del nuevo hilo...'} value={body} onChange={(e)=>setBody(e.target.value)} rows={4} />
      <button type="submit">Enviar</button>
    </form>
  );
};

export default ContentForm;
